   '[{"id":"a","text":"High resin content"},{"id":"b","text":"Presence of large rays"},{"id":"c","text":"Interlocked grain pattern"},{"id":"d","text":"Uniform texture"}]'::jsonb, 'b'),
  ('fu-g00483', 'forest-utilization', 'wood-structure-identification', 'Easy', 'mock',
   'Which feature distinguishes ''Kamagong'' (Diospyros blancoi) from other Philippine hardwoods?',
   '[{"id":"a","text":"Very dark heartwood color"},{"id":"b","text":"Presence of silica bodies"},{"id":"c","text":"Straight grain pattern"},{"id":"d","text":"Large vessel pores"}]'::jsonb, 'a'),
  ('fu-g00484', 'forest-utilization', 'wood-structure-identification', 'Easy', 'mock',
