  ('fu-g00485', 'forest-utilization', 'wood-structure-identification', 'Easy', 'mock',
   'Which characteristic helps in identifying ''Apitong'' (Dipterocarpus grandiflorus) wood?',
   '[{"id":"a","text":"Straight grain pattern"},{"id":"b","text":"Dark sapwood color"},{"id":"c","text":"High density"},{"id":"d","text":"Presence of resin canals"}]'::jsonb, 'd'),
  ('fu-g00486', 'forest-utilization', 'wood-structure-identification', 'Easy', 'mock',
   'Which anatomical feature is used to identify ''Ipil'' (Intsia bijuga) wood?',
   '[{"id":"a","text":"Interlocked grain pattern"},{"id":"b","text":"Dark heartwood color"},{"id":"c","text":"High silica content"},{"id":"d","text":"Presence of tyloses in vessel elements"}]'::jsonb, 'd'),
  ('fu-g00487', 'forest-utilization', 'wood-structure-identification', 'Easy', 'mock',
   'What is the main identifying feature of the wood of ''Mayapis'' (Shorea palosapis)?',
