  ('fu-g00488', 'forest-utilization', 'wood-structure-identification', 'Easy', 'mock',
   'Which feature distinguishes ''Yakal'' (Shorea astylosa) wood from other dipterocarps?',
   '[{"id":"a","text":"Presence of parenchyma bands"},{"id":"b","text":"Distinctive spiral grain"},{"id":"c","text":"Large resin canals"},{"id":"d","text":"High density and hardness"}]'::jsonb, 'd'),
  ('fu-g00489', 'forest-utilization', 'wood-structure-identification', 'Easy', 'mock',
   'Which wood anatomical feature helps identify ''Benguet Pine'' (Pinus kesiya) in the Philippines?',
   '[{"id":"a","text":"Distinctive knotty grain"},{"id":"b","text":"Smooth, even texture"},{"id":"c","text":"Presence of large resin canals"},{"id":"d","text":"Coarse texture with dark streaks"}]'::jsonb, 'c'),
  ('fu-g00490', 'forest-utilization', 'wood-structure-identification', 'Easy', 'mock',
   'Which feature is used to identify the wood of ''Malabayabas'' (Tristaniopsis decorticata)?',
   '[{"id":"a","text":"Distinct yellowish sapwood"},{"id":"b","text":"Dark, wavy grain"},{"id":"c","text":"Fine texture with parenchyma bands"},{"id":"d","text":"Interlocked grain with a rough texture"}]'::jsonb, 'd'),
