  ('fu-g00495', 'forest-utilization', 'wood-structure-identification', 'Easy', 'mock',
   'Which anatomical feature helps identify ''Benguet Pine'' (Pinus kesiya) wood?',
   '[{"id":"a","text":"Presence of spiral grain"},{"id":"b","text":"Resinous scent"},{"id":"c","text":"Conspicuous medullary rays"},{"id":"d","text":"Presence of resin ducts"}]'::jsonb, 'd'),
  ('fu-g00496', 'forest-utilization', 'wood-structure-identification', 'Easy', 'mock',
   'Which feature is used to identify ''White Lauan'' (Shorea contorta) wood?',
